/* All four answers remain available when JavaScript is disabled. */
(()=>{const section=document.querySelector('.buyer-section');if(!section)return;const buttons=[...section.querySelectorAll('[data-buyer-choice]')];const panels=[...section.querySelectorAll('[data-buyer-panel]')];function select(key){buttons.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.buyerChoice===key)));panels.forEach(panel=>panel.hidden=panel.dataset.buyerPanel!==key)}buttons.forEach(button=>button.addEventListener('click',()=>{select(button.dataset.buyerChoice);const panel=panels.find(item=>item.dataset.buyerPanel===button.dataset.buyerChoice);const title=panel?.querySelector('h3');if(title){title.setAttribute('tabindex','-1');title.focus({preventScroll:true})}}));select('settlement')})();
